// TS skeleton
interface Message { id: string; payload: any; metadata?: { strategy?: string } }
type RoutingDecision = { destination: string; retry?: number }
interface FailureStrategy { onFailure(msg: Message, ctx: any): RoutingDecision }
class DLQRouter {
  private registry = new Map<string, FailureStrategy>()
  register(name: string, s: FailureStrategy) { this.registry.set(name, s) }
  route(msg: Message) { const name = msg.metadata?.strategy ?? 'DeadLetter'; const s = this.registry.get(name); return s?.onFailure(msg, {}) }
}
